import {products,getProduct,calculateOrder} from './catalog.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem('luma-'+key))??fallback}catch{return fallback}};
const state={lang:read('lang','en'),currency:read('currency','USD'),cart:read('cart',[]).filter(i=>getProduct(i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=20),favorites:read('favorites',[]).filter(id=>getProduct(id)),compare:read('compare',[]).filter(id=>getProduct(id)).slice(0,3),orders:read('orders',[]),routine:read('routine',{cleanse:'dew-cleanser',serum:'morning-serum',moisturize:'cloud-cream',protect:'sun-veil'}),period:'am',gift:read('gift',{ids:[],color:'#ddd5c5',note:''}),giftInCart:read('giftInCart',null),consent:read('consent',null),category:'all',search:'',sort:'featured',maxPrice:50,texture:'cream',quizStep:0,quiz:{skin:'',goal:'',time:''},qty:1,code:read('code',''),shipping:'standard'};
const persist=(key,value)=>{try{localStorage.setItem('luma-'+key,JSON.stringify(value))}catch{toast(t('Storage is unavailable. Keep this tab open.','浏览器存储不可用，请保持页面开启。'))}};
let session;try{session=sessionStorage.getItem('luma-session');if(!session){session=crypto.randomUUID();sessionStorage.setItem('luma-session',session)}}catch{session=crypto.randomUUID()}
const t=(en,zh)=>state.lang==='zh'?zh:en;
const pname=p=>state.lang==='zh'?p.zh:p.name;
const desc=p=>state.lang==='zh'?p.descZh:p.desc;
const money=n=>new Intl.NumberFormat(state.lang==='zh'?'zh-CN':'en-US',{style:'currency',currency:state.currency,maximumFractionDigits:2}).format(n*({USD:1,EUR:.92,GBP:.78,CNY:7.2}[state.currency]||1));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=()=>[['all',t('All essentials','全部商品')],['cleanse',t('Cleanse','清洁')],['serum',t('Treat','精华')],['moisturize',t('Moisturize','保湿')],['protect',t('Protect','防护')]];
const skinName=s=>({dry:t('Dry','干性'),oily:t('Oily','油性'),combination:t('Combination','混合性'),sensitive:t('Sensitive','敏感性')}[s]||s);
const route=()=>location.hash.slice(1).split('/')[0]||'home';
const saveCart=()=>{persist('cart',state.cart);persist('giftInCart',state.giftInCart);updateCartCount()};
const totalQty=()=>state.cart.reduce((n,i)=>n+i.qty,0);
function updateCartCount(){$('#cart-count').textContent=totalQty()}
function translateStatic(){$$('[data-en]').forEach(el=>el.textContent=el.dataset[state.lang]||el.dataset.en);document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';$('#language').value=state.lang;$('#currency').value=state.currency;updateCartCount()}
let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function track(name,product){if(state.consent!==true||route()==='analytics')return;fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),session,name,product,route:route(),device:innerWidth<761?'mobile':'desktop'}),keepalive:true}).catch(()=>{});}
function art(p,cls=''){return `<div class="product-art ${cls}" aria-label="${esc(pname(p))} ${t('illustration','商品示意图')}"><div class="bottle ${p.shape}" style="--bottle:${p.color}"><div class="bottle-label"><b>luma</b><small>R I T U A L</small><em>${esc(p.name)}</em><span>${esc(p.tag)}<br>${p.size}</span></div></div></div>`}
function card(p,mini=false){return `<article class="product-card" ${mini?'draggable="true"':''} data-product="${p.id}"><span class="product-badge">${esc(state.lang==='zh'?p.badgeZh:p.badge)}</span><button class="favorite ${state.favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${t('Save','收藏')} ${esc(pname(p))}" aria-pressed="${state.favorites.includes(p.id)}">${state.favorites.includes(p.id)?'♥':'♡'}</button><a href="#product/${p.id}" class="art-link">${art(p)}</a><div class="product-info"><div><a href="#product/${p.id}"><h3>${esc(pname(p))}</h3></a><p>${esc(state.lang==='zh'?p.tagZh:p.tag)} · ${p.size}</p></div><span class="price">${money(p.price)}</span></div><div class="product-actions"><button class="quick-add" data-action="${mini?'routine-pick':'add'}" data-id="${p.id}">${mini?t('Add to ritual +','加入护理搭配 +'):t('Add to bag +','加入购物车 +')}</button><label class="compare-check"><input type="checkbox" data-action="compare-toggle" data-id="${p.id}" ${state.compare.includes(p.id)?'checked':''}> ${t('Compare','对比')}</label></div></article>`}
function intro(eyebrow,title,text){return `<div class="page-intro"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${text}</p></div>`}
const cards=items=>items.map(p=>card(p)).join('');
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">${t('THE ART OF EVERYDAY CARE','把日常，过成护理仪式')}</span><h1>${t('A little ritual.<br>A softer day.','一点仪式感，<br>柔软每一天。')}</h1><p>${t('Thoughtful skincare for your everyday. Simple textures, quiet moments, and a little more you.','用心设计的日常护理。简单的质地，安静的片刻，和更多属于自己的时间。')}</p><div class="btn-row"><a class="btn" href="#shop">${t('Explore the collection','探索全部商品')} <span>↗</span></a><a class="text-link" href="#quiz">${t('Find your ritual','找到你的护理')}</a></div><div class="hero-footnote"><span>✧ ${t('Considered ingredients','用心挑选的成分')}</span><span>◌ ${t('Made for your everyday','为日常而设计')}</span></div></div><div class="hero-visual"><span class="visual-note">THE EVERYDAY ESSENTIALS / 01</span><div class="hero-set">${art(products[0])}${art(products[1])}${art(products[2])}</div><div class="hero-seal">A LITTLE<b>care</b>GOES A LONG WAY</div><span class="hero-caption">LESS, BUT LOVELY. · LUMA RITUAL</span></div></section><div class="benefits"><span><i>✧</i>${t('THOUGHTFULLY FORMULATED CONCEPTS','用心设计的护理概念')}</span><span><i>◯</i>${t('A SIMPLER DAILY RITUAL','更简单的日常护理')}</span><span><i>↗</i>${t('FREE SHIPPING ON $75+','满 $75 免费标准配送')}</span><span><i>♡</i>${t('A LITTLE MOMENT FOR YOU','留给自己的一点时间')}</span></div><section class="section"><div class="section-heading"><div><span class="eyebrow">${t('GOOD DAYS START HERE','美好一天，从这里开始')}</span><h2>${t('Meet your everyday favorites.','遇见日常心选。')}</h2></div><a class="text-link" href="#shop">${t('Shop all essentials ↗','探索全部商品 ↗')}</a></div><div class="product-grid">${cards(products.slice(0,4))}</div></section><section class="ritual-banner"><div class="ritual-graphic">${[[t('Cleanse','清洁'),'01'],[t('Treat','精华'),'02'],[t('Moisturize','保湿'),'03'],[t('Protect','防护'),'04']].map(([n,i])=>`<div class="step-orb"><span>${i}</span>${n}<span>✧</span></div>`).join('')}</div><div class="content"><span class="eyebrow">${t('YOUR SKIN. YOUR PACE.','你的肌肤，你的节奏')}</span><h2>${t('A ritual that<br>feels like you.','为自己，<br>搭配一份日常。')}</h2><p>${t('Build a little routine, one thoughtful step at a time. Mix, match, and make it your own.','从一个步骤开始，组合你的早晚护理，让日常更有条理。')}</p><a class="btn" href="#routine">${t('Build your ritual','搭配我的护理')} ↗</a></div></section><section class="section editorial"><div class="editorial-art"><div class="texture-blob cream"></div><span class="texture-watermark">TEXTURE STUDY / CREAM · DIGITAL VISUALIZATION</span></div><div><span class="eyebrow">${t('FEEL-GOOD FORMULAS','从质地，感受护理')}</span><h2>${t('Good care begins<br>with a feeling.','好的护理，<br>从触感开始。')}</h2><p>${t('Silky, cloud-soft, or barely there. Get closer to the textures that make each ritual a moment worth keeping.','丝滑、绵密，或轻盈如水。走近不同质地，找到你喜欢的护理体验。')}</p><a class="text-link" href="#texture">${t('Step into the texture library ↗','走进质地实验室 ↗')}</a></div></section><section class="quote"><span class="eyebrow">THE LUMA PHILOSOPHY</span><h2>${t('“A little less rushing.<br>A little more looking after you.”','“少一点匆忙，<br>多一点照顾自己。”')}</h2><p>${t('OUR FICTIONAL BRAND MANIFESTO','虚构品牌理念 · 展示内容')}</p></section><section class="section"><div class="discovery-grid"><article class="discovery-card"><span class="eyebrow">A LITTLE SOMETHING, WITH LOVE</span><h3>${t('Care, beautifully<br>wrapped.','把关怀，<br>装进礼盒。')}</h3><p>${t('Curate a gift as thoughtful as they are.','挑选商品、定制包装，再写下一句心意。')}</p><a href="#gift" class="text-link">${t('Visit the gifting studio ↗','定制我的礼盒 ↗')}</a><div class="mini-art">${art(products[7])}</div></article><article class="discovery-card"><span class="eyebrow">THE EVERYDAY EDIT</span><h3>${t('At home in<br>your everyday.','让护理，<br>融入生活。')}</h3><p>${t('Discover the essentials in their natural habitat.','点击场景中的商品，发现你的日常搭配。')}</p><a href="#scene" class="text-link">${t('Shop the scene ↗','探索场景好物 ↗')}</a><div class="mini-art">${art(products[4])}</div></article></div></section>`}
function shop(favorites=false){let list=products.filter(p=>(!favorites||state.favorites.includes(p.id))&&(state.category==='all'||p.category===state.category)&&p.price<=state.maxPrice&&`${p.name} ${p.zh} ${p.tag} ${p.ingredients.join(' ')} ${p.ingredientsZh.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='low')list.sort((a,b)=>a.price-b.price);if(state.sort==='high')list.sort((a,b)=>b.price-a.price);if(state.sort==='name')list.sort((a,b)=>pname(a).localeCompare(pname(b)));return `${intro(t('THE COLLECTION','日常护理系列'),favorites?t('Your saved favorites.','收藏你的心动。'):t('A little care, every day.','每天，一点好好照顾。'),t('Thoughtful essentials. Find your texture, your pace, your ritual.','发现用心设计的护理单品，找到自己的质地、节奏和日常。'))}<section class="section"><div class="shop-controls"><div class="chips">${cats().map(([id,n])=>`<button class="chip ${state.category===id?'active':''}" data-action="category" data-id="${id}">${n}</button>`).join('')}</div><div class="shop-search"><input id="search" class="search-input" type="search" placeholder="${t('Search essentials…','搜索商品或成分…')}" value="${esc(state.search)}" aria-label="${t('Search products','搜索商品')}"><select id="sort" class="sort-select" aria-label="${t('Sort products','商品排序')}">${[['featured',t('Featured','推荐排序')],['low',t('Price: low to high','价格从低到高')],['high',t('Price: high to low','价格从高到低')],['name',t('Name','名称排序')]].map(([v,n])=>`<option value="${v}" ${state.sort===v?'selected':''}>${n}</option>`).join('')}</select></div></div><label class="range-filter">${t('Maximum price','最高价格')} <input id="max-price" type="range" min="20" max="50" value="${state.maxPrice}"> <span>${money(state.maxPrice)}</span></label><div class="filter-result">${list.length} ${t('essentials','件商品')} · ${t('Prices and products are illustrative','商品及价格均为演示')}</div><div class="product-grid">${list.length?cards(list):empty(t('Nothing here just yet.','暂时没有商品。'),t('Try another search or save a few favorites.','换个关键词，或先收藏喜欢的商品。'),'#shop',t('Browse all','浏览全部'))}</div></section>`}
function empty(title,text,href,label){return `<div class="empty"><h3>${title}</h3><p>${text}</p><a class="btn secondary" href="${href}">${label}</a></div>`}
function productPage(p){if(!p)return `${intro('404',t('A little lost?','这个商品不在这里。'),t('Let’s get you back to the collection.','回到商品系列继续探索。'))}<section class="section">${empty('404','','#shop',t('Shop all','全部商品'))}</section>`;return `<section class="section"><a class="text-link" href="#shop">← ${t('The collection','全部商品')}</a><div class="detail-layout" style="margin-top:30px"><div><div data-action="rotate" data-id="${p.id}" tabindex="0" role="button" aria-label="${t('Explore 360 degree product','查看 360 度商品模型')}">${art(p,'detail-art')}</div><div class="detail-tabs"><button class="btn secondary small" data-action="rotate" data-id="${p.id}">↻ ${t('Explore in 360°','360° 查看')}</button><button class="btn secondary small" data-action="texture-link" data-id="${p.id}">${t('Feel the texture','探索商品质地')} ↗</button></div></div><div class="detail-content"><span class="eyebrow">${esc(state.lang==='zh'?p.tagZh:p.tag)}</span><h1>${esc(pname(p))}</h1><p class="description">${esc(desc(p))}</p><div class="detail-price">${money(p.price)} <small>${p.size} · ${t('Illustrative price','演示价格')}</small></div><div class="skin-labels">${p.skin.map(s=>`<span>${skinName(s)}</span>`).join('')}</div><div class="field"><label for="product-size">${t('Size','规格')}</label><select id="product-size"><option>${p.size} · ${t('Full size','标准装')}</option></select></div><div class="detail-add"><div class="quantity"><button data-action="detail-minus" aria-label="Decrease quantity">−</button><span id="detail-qty">${state.qty}</span><button data-action="detail-plus" aria-label="Increase quantity">+</button></div><button class="btn" data-action="detail-add" data-id="${p.id}">${t('Add to bag','加入购物车')} · ${money(p.price*state.qty)}</button></div><div class="btn-row" style="margin-top:15px"><button class="text-link" data-action="favorite" data-id="${p.id}">${state.favorites.includes(p.id)?'♥':'♡'} ${t('Save for later','收藏商品')}</button><button class="text-link" data-action="compare-toggle" data-id="${p.id}">${t('Add to comparison','加入对比')} +</button></div><p class="content-note">${t('Complimentary standard shipping on $75+. Demo store: no actual sale.','满 $75 免费标准配送。演示商店，不进行真实销售。')}</p><div class="details-accordion"><details open><summary>${t('The ingredients edit','成分一览')}</summary><p>${esc((state.lang==='zh'?p.ingredientsZh:p.ingredients).join(' · '))}</p><p>${t('Illustrative formula only. Not a verified ingredient list or efficacy claim.','仅为配方展示，不构成经验证的成分表或功效声明。')}</p></details><details><summary>${t('How it fits your ritual','如何融入护理流程')}</summary><p>${t('Use as the '+p.category+' step in your routine. Review actual product directions before using any real skincare product.','可作为日常护理的'+cats().find(([id])=>id===p.category)?.[1]+'步骤。使用真实护肤品前请查看实际产品说明。')}</p></details><details><summary>${t('Delivery & returns','配送与退换货')}</summary><p>${t('Demo standard delivery: 5–8 business days. Express: 2–4 business days. These are illustrative estimates; no parcels are sent.','标准配送演示时效：5–8 个工作日；快递：2–4 个工作日。均为示例，不实际发货。')}</p><a class="text-link" href="#help">${t('View all policies','查看完整说明')}</a></details></div><div class="review"><span class="pill">${t('SAMPLE REVIEW · NOT A REAL CUSTOMER','示例评价 · 非真实用户反馈')}</span><div class="stars">★★★★★</div><h3>${t('“A lovely little everyday ritual.”','“让日常多一份小小仪式感。”')}</h3><p>${t('A fictional review demonstrating the product review layout.','这是一条虚构评价，用于展示商品评价模块。')}</p></div></div></div></section><section class="section"><div class="section-heading"><h2>${t('Better, together.','好搭档，一起选。')}</h2><a href="#routine" class="text-link">${t('Build a ritual ↗','搭配护理 ↗')}</a></div><div class="product-grid">${cards(products.filter(x=>x.id!==p.id).slice(0,4))}</div></section>`}
function routinePage(){const steps=state.period==='am'?['cleanse','serum','moisturize','protect']:['cleanse','serum','moisturize'];const selected=steps.map(s=>getProduct(state.routine[s])).filter(Boolean);return `${intro(t('THE RITUAL BUILDER','护理搭配台'),t('Make a little time for you.','为自己，留一点时间。'),t('Choose your steps. Drag an essential into a matching slot, or use the dropdowns.','选择护理步骤。将商品拖入对应位置，或使用下拉框选择；手机也能轻松搭配。'))}<section class="section"><div class="workspace"><div class="workspace-heading"><h3>${t('Your everyday ritual','你的日常护理')}</h3><div class="chips"><button class="chip ${state.period==='am'?'active':''}" data-action="period" data-id="am">☀ ${t('Morning','晨间')}</button><button class="chip ${state.period==='pm'?'active':''}" data-action="period" data-id="pm">☾ ${t('Evening','晚间')}</button></div></div><div class="routine-slots">${steps.map((s,i)=>{const p=getProduct(state.routine[s]);return `<div class="routine-slot" data-step="${s}"><span class="slot-label">0${i+1} / ${cats().find(([id])=>id===s)?.[1]}</span>${p?art(p):'<div class="placeholder">＋</div>'}<strong>${p?esc(pname(p)):t('Your choice','你的选择')}</strong><select data-routine="${s}" aria-label="${s}"><option value="">${t('Choose an essential','选择商品')}</option>${products.filter(p=>p.category===s).map(x=>`<option value="${x.id}" ${x.id===p?.id?'selected':''}>${esc(pname(x))} · ${money(x.price)}</option>`).join('')}</select></div>`}).join('')}</div><div class="workspace-footer"><p>${selected.length} ${t('steps','个步骤')} · <strong>${money(selected.reduce((n,p)=>n+p.price,0))}</strong><br><small>${t('A concept pairing, not medical advice.','示例搭配，不作为医疗建议。')}</small></p><button class="btn" data-action="routine-add" ${!selected.length?'disabled':''}>${t('Add ritual to bag','整套加入购物车')} ↗</button></div></div><div class="section-heading" style="margin-top:45px"><h2>${t('Your ritual, your choices.','搭配，由你决定。')}</h2><a href="#quiz" class="text-link">${t('Need a little guidance? ↗','需要一点搭配灵感？↗')}</a></div><div class="mini-catalog">${products.map(p=>card(p,true)).join('')}</div></section>`}
function quizPage(){const steps=[{title:t('How does your skin usually feel?','你的肌肤通常是什么状态？'),key:'skin',options:[['dry',t('Dry','干性'),t('Often feels tight','经常有紧绷感')],['oily',t('Oily','油性'),t('Often looks shiny','容易泛油光')],['combination',t('Combination','混合性'),t('A little of both','部分油，部分干')],['sensitive',t('Sensitive','敏感性'),t('Prefers gentle care','更偏好温和护理')]]},{title:t('What texture do you enjoy?','你更喜欢哪一种质地？'),key:'goal',options:[['light',t('Fresh & light','清爽轻盈'),t('Barely-there layers','喜欢轻薄的肤感')],['rich',t('Soft & comforting','柔软滋润'),t('A cushioned finish','喜欢绵密包裹感')]]},{title:t('When is your little ritual?','想搭配哪个时段的护理？'),key:'time',options:[['am',t('A fresh morning','清新晨间'),t('Start the day slowly','从容开始新的一天')],['pm',t('A quiet evening','安静晚间'),t('Unwind, one step at a time','慢慢放松下来')]]}];if(state.quizStep>=3){const rec=quizRecommendations();return `${intro(t('YOUR RITUAL EDIT','为你搭配'),t('A little routine, just for you.','你的日常护理灵感。'),t('Based on your selected preferences. Illustrative suggestions only, not a skin diagnosis.','根据你选择的偏好生成，仅为示例建议，不进行肤质诊断。'))}<section class="section"><div class="quiz-result"><span class="eyebrow">${skinName(state.quiz.skin)} / ${state.quiz.time==='pm'?t('EVENING','晚间'):t('MORNING','晨间')}</span><h2>${state.quiz.goal==='rich'?t('A softer kind of care.','柔润舒适的护理。'):t('Keep it light. Keep it simple.','清爽一些，简单一些。')}</h2><p>${t('We matched your preferred texture and routine time to these concept products. Real product compatibility depends on the actual formula and your individual needs.','我们按质地偏好和护理时段搭配了这些概念商品。真实适用性取决于实际配方和个人情况。')}</p><div class="btn-row"><button class="btn" data-action="quiz-routine">${t('Use this ritual','使用这套搭配')} ↗</button><button class="text-link" data-action="quiz-reset">${t('Start again','重新选择')}</button></div></div><div class="product-grid">${cards(rec)}</div></section>`;}const s=steps[state.quizStep];return `${intro(t('FIND YOUR RITUAL','找到你的日常护理'),t('A few questions. A little clarity.','几个小问题，一点新灵感。'),t('Tell us your preferences. We’ll put together a simple concept routine.','告诉我们你的护理偏好，组合一套简单的示例流程。'))}<section class="section"><div class="quiz-card"><div class="progress-dots">${steps.map((_,i)=>`<i class="${i<=state.quizStep?'active':''}"></i>`).join('')}</div><span class="eyebrow">0${state.quizStep+1} / 03</span><h2>${s.title}</h2><div class="quiz-options">${s.options.map(([id,n,d])=>`<button class="quiz-option ${state.quiz[s.key]===id?'selected':''}" data-action="quiz-option" data-key="${s.key}" data-id="${id}" aria-pressed="${state.quiz[s.key]===id}"><strong>${n}</strong><span>${d}</span></button>`).join('')}</div><div class="btn-row"><button class="btn" data-action="quiz-next" ${!state.quiz[s.key]?'disabled':''}>${state.quizStep===2?t('See my ritual','查看我的搭配'):t('Continue','继续')} →</button>${state.quizStep?`<button class="text-link" data-action="quiz-back">← ${t('Back','上一步')}</button>`:''}</div><p class="quiz-warning">${t('No photo or health information is collected. Choices remain in this tab. This is a preference guide, not a diagnosis.','无需上传照片或健康信息，选择仅保留在当前页面。这是偏好向导，不是肌肤诊断。')}</p></div></section>`}
function quizRecommendations(){const light=state.quiz.skin==='oily'||(state.quiz.skin==='combination'&&state.quiz.goal==='light');return [products[0],getProduct(light?'balance-serum':'morning-serum'),getProduct(light?'water-gel':'cloud-cream'),...(state.quiz.time==='pm'?[]:[products[3]])]}
const textures=()=>({cream:{name:t('Cloud-soft cream','绵密乳霜'),desc:t('A soft, cushioned texture with a rich, comforting feel.','柔软绵密、富有包裹感的质地。'),rich:90,light:25,spread:60},gel:{name:t('Weightless gel','轻盈凝露'),desc:t('A cool, translucent texture with a fresh, lightweight feel.','清凉通透、清新轻盈的质地。'),rich:25,light:95,spread:90},serum:{name:t('Silky serum','丝滑精华'),desc:t('A fluid, fast-spreading texture designed for easy layering.','流动易延展，适合叠加护理的质地。'),rich:40,light:85,spread:95},oil:{name:t('Golden face oil','金色精华油'),desc:t('A glossy, fluid texture with a silky finishing feel.','莹润流动、触感丝滑的护理油质地。'),rich:85,light:40,spread:90}});
function texturePage(){const tx=textures()[state.texture];return `${intro(t('THE TEXTURE LIBRARY','质地实验室'),t('A feeling, before the first drop.','在第一滴之前，感受质地。'),t('Explore a digital interpretation of our concept textures. Click to spread, or adjust the light.','探索概念质地的数字模拟。点击涂抹，或调节光线，观察变化。'))}<section class="section"><div class="texture-layout"><div><div class="texture-stage" id="texture-stage" role="button" tabindex="0" aria-label="${t('Tap to spread texture','点击模拟涂抹质地')}"><div class="texture-blob ${state.texture}"></div><span class="texture-watermark">DIGITAL TEXTURE STUDY · ${t('TAP TO SPREAD','点击模拟涂抹')}</span></div><p class="content-note">${t('Illustrative animation. Texture scores below are sample visual descriptors, not laboratory measurements.','示意动画。下方数值为展示用的感官描述，不是实验检测数据。')}</p></div><div class="texture-controls"><div class="chips">${Object.keys(textures()).map(k=>`<button class="chip ${state.texture===k?'active':''}" data-action="texture" data-id="${k}">${({cream:t('Cream','乳霜'),gel:t('Gel','凝露'),serum:t('Serum','精华'),oil:t('Oil','护理油')})[k]}</button>`).join('')}</div><h2 style="margin-top:35px">${tx.name}</h2><p>${tx.desc}</p><div class="texture-stats">${[[t('Richness','丰润感'),tx.rich],[t('Lightness','轻盈感'),tx.light],[t('Spread','延展感'),tx.spread]].map(([n,v])=>`<div>${n}<i><b style="width:${v}%"></b></i></div>`).join('')}</div><label for="texture-light">${t('Studio light','调节光线')}</label><input id="texture-light" type="range" min="75" max="125" value="100"><div class="btn-row" style="margin-top:25px"><button class="btn secondary" data-action="spread">${t('Try a swipe','模拟涂抹')} ↗</button><button class="text-link" data-action="reset-texture">${t('Reset','重置')}</button></div></div></div><div class="section-heading" style="margin-top:50px"><h2>${t('Find it in your ritual.','把这份触感，加入日常。')}</h2></div><div class="product-grid">${cards(products.filter(p=>p.texture===state.texture))}</div></section>`}
function giftPage(){const choices=state.gift.ids.map(getProduct).filter(Boolean);return `${intro(t('THE GIFTING STUDIO','礼盒定制工作室'),t('A little care, beautifully wrapped.','把心意，好好装起来。'),t('Choose up to three essentials, pick a box, and write a little note.','选择 1～3 件商品，挑选包装颜色，再写下一句心意。'))}<section class="section"><div class="gift-layout"><div class="gift-preview"><span class="eyebrow">YOUR LITTLE GIFT / LIVE PREVIEW</span><div class="gift-box" style="--gift-color:${state.gift.color}">${[0,1,2].map(i=>choices[i]?art(choices[i]):'<div class="placeholder">＋</div>').join('')}</div><div class="gift-card-preview" id="gift-card-preview">${esc(state.gift.note||t('A little something, just for you.','一点小心意，送给特别的你。'))}</div></div><div><h3>${t('01. Pick your essentials','01. 挑选礼盒商品')}</h3><p><small>${choices.length}/3 ${t('selected · $6 gift packaging','已选 · 礼盒包装费 $6')}</small></p><div class="gift-list">${products.map(p=>`<button class="gift-choice ${state.gift.ids.includes(p.id)?'selected':''}" data-action="gift-pick" data-id="${p.id}" aria-pressed="${state.gift.ids.includes(p.id)}">${art(p)}<span><strong>${esc(pname(p))}</strong><small>${money(p.price)} ${state.gift.ids.includes(p.id)?'✓':'＋'}</small></span></button>`).join('')}</div><h3 style="margin-top:30px">${t('02. Choose a little color','02. 选择包装颜色')}</h3><div class="swatches">${[['#ddd5c5',t('Oat','燕麦')],['#b9c7ad',t('Sage','鼠尾草')],['#d8b6ac',t('Rose','玫瑰')]].map(([c,n])=>`<button class="swatch ${state.gift.color===c?'active':''}" style="--swatch:${c}" data-action="gift-color" data-id="${c}" aria-label="${n}" title="${n}" aria-pressed="${state.gift.color===c}"></button>`).join('')}</div><h3>${t('03. Make it personal','03. 写一句心意')}</h3><label class="field" for="gift-note">${t('Gift message (120 characters)','礼物留言（最多 120 字）')}<textarea class="gift-note" id="gift-note" rows="3" maxlength="120" placeholder="${t('A little note…','写下一句祝福…')}">${esc(state.gift.note)}</textarea></label><div class="workspace-footer"><strong>${money(choices.reduce((n,p)=>n+p.price,0)+(choices.length?6:0))}</strong><button class="btn" data-action="gift-add" ${!choices.length?'disabled':''}>${t('Add gift to bag','礼盒加入购物车')} ↗</button></div><p class="content-note">${t('One gift box per order. Your selected packaging and note travel with the cart.','每单支持一个礼盒，包装和留言会保存在购物车中。')}</p></div></div></section>`}
function scenePage(){return `${intro(t('THE EVERYDAY EDIT','生活场景选购'),t('At home in your everyday.','护理，就在日常里。'),t('A quiet corner, a few good essentials. Tap a + to explore and shop the scene.','一个安静角落，几件心选好物。点击 + 查看场景商品并加购。'))}<section class="section"><div class="scene-stage"><span class="scene-label">THE SLOW MORNING / 01</span><div class="scene-mirror"></div><div class="scene-shelf"></div><div class="scene-vase"></div><div class="scene-branch"></div>${[[products[0],'12%','8%'],[products[1],'35%','30%'],[products[2],'52%','51%']].map(([p,x,m])=>`<div class="scene-product" style="--x:${x};--mobile-x:${m}">${art(p)}<button class="hotspot" data-action="scene-product" data-id="${p.id}" aria-label="${t('Explore','查看')} ${esc(pname(p))}">+</button></div>`).join('')}<span class="scene-caption">${t('The art of a slower morning.','慢一点，开始美好早晨。')}</span></div><p class="content-note">${t('Digitally illustrated shopping scene. Concept products shown.','数字绘制的购物场景，商品均为概念展示。')}</p><div class="section-heading" style="margin-top:35px"><h2>${t('In this little corner.','这个角落里的好物。')}</h2><button class="text-link" data-action="scene-add-all">${t('Add the scene to bag +','场景商品一键加购 +')}</button></div><div class="product-grid">${cards(products.slice(0,3))}</div></section>`}
function comparePage(){const list=state.compare.map(getProduct).filter(Boolean);const row=(name,fn)=>`<tr><th scope="row">${name}</th>${list.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`;return `${intro(t('SIDE BY SIDE','商品对比台'),t('A little clarity, side by side.','并排看看，选得更清楚。'),t('Compare up to three essentials. Select products from the collection to build your edit.','最多对比 3 件商品。在商品列表勾选「对比」，找到适合自己的选择。'))}<section class="section"><div class="btn-row" style="margin-bottom:25px"><a class="btn secondary" href="#shop">${t('Choose products','挑选对比商品')} +</a>${list.length?`<button class="text-link" data-action="compare-clear">${t('Clear comparison','清空对比')}</button>`:''}</div>${list.length?`<div class="comparison-wrap"><table class="comparison"><thead><tr><th>${t('Your essentials','你的心选')}</th>${list.map(p=>`<th>${art(p)}<h3>${esc(pname(p))}</h3><button class="text-link" data-action="compare-toggle" data-id="${p.id}">${t('Remove','移除')} ×</button></th>`).join('')}</tr></thead><tbody>${row(t('Price','价格'),p=>money(p.price))}${row(t('Size','容量'),p=>p.size)}${row(t('Texture','质地'),p=>textures()[p.texture].name)}${row(t('Step','护理步骤'),p=>cats().find(([id])=>id===p.category)?.[1])}${row(t('Skin preference','肤质偏好'),p=>p.skin.map(skinName).join(' / '))}${row(t('Concept ingredients','示例成分'),p=>esc((state.lang==='zh'?p.ingredientsZh:p.ingredients).join(' · ')))}${row('',p=>`<button class="btn small" data-action="add" data-id="${p.id}">${t('Add to bag','加入购物车')} +</button>`)}</tbody></table></div>`:empty(t('Room for a little comparison.','给心选商品，一点对比空间。'),t('Pick two or three products to see their details side by side.','选取 2～3 件商品，并排查看详情。'),'#shop',t('Explore the collection','探索全部商品'))}</section>`}
function cartOrder(){return state.cart.length?calculateOrder(state.cart,state.code,state.shipping,!!state.giftInCart):null}
function summaryLines(o){return `<div class="summary-line"><span>${t('Subtotal','商品小计')}</span><span>${money(o.subtotal)}</span></div>${o.discount?`<div class="summary-line"><span>LUMA10 · ${t('10% off','九折优惠')}</span><span>−${money(o.discount)}</span></div>`:''}<div class="summary-line"><span>${t('Delivery','运费')}</span><span>${o.delivery?money(o.delivery):t('Complimentary','免费')}</span></div>${o.packaging?`<div class="summary-line"><span>${t('Gift packaging','礼盒包装')}</span><span>${money(o.packaging)}</span></div>`:''}<div class="summary-line"><span>${t('Tax (demo)','税费（演示）')}</span><span>${money(0)}</span></div><div class="summary-line total"><span>${t('Total','合计')}</span><strong>${money(o.total)}</strong></div>`}
function orderLine(i){const p=getProduct(i.id);if(!p)return '';return `<div class="order-line">${art(p)}<div class="line-text"><h3>${esc(pname(p))}</h3><p>${p.size} · ${t('Quantity','数量')} ${i.qty}</p></div><span>${money(p.price*i.qty)}</span></div>`}
function checkoutPage(){const o=cartOrder();if(!o)return `<section class="section">${empty(t('Your bag is waiting.','购物车还在等你。'),t('Add a little care before checking out.','先选几件好物，再来结账吧。'),'#shop',t('Explore essentials','挑选商品'))}</section>`;return `${intro(t('A LITTLE CARE, ON ITS WAY','心选好物，即将出发'),t('The final little step.','最后一步，小小仪式。'),t('This is a simulated checkout. No card details, charge, or shipment.','这是模拟结账，不填写真实银行卡信息，不收款，不实际发货。'))}<section class="section"><div class="checkout-layout"><form class="checkout-form" id="checkout-form"><div class="demo-notice">${t('Use fictional contact and address details. They stay in your browser and are not sent to our server.','请使用虚构联系信息和地址。它们仅保存在当前浏览器，不发送至服务端。')}</div><h3>${t('Contact','联系信息')}</h3><label class="field">${t('Email','电子邮箱')}<input type="email" name="email" required placeholder="demo@example.com" autocomplete="off" maxlength="100"></label><h3>${t('Delivery details','配送信息')}</h3><div class="form-row"><label class="field">${t('First name','名字')}<input name="firstName" required maxlength="50" placeholder="Alex" autocomplete="off"></label><label class="field">${t('Last name','姓氏')}<input name="lastName" required maxlength="50" placeholder="Demo" autocomplete="off"></label></div><label class="field">${t('Country / region','国家 / 地区')}<select name="country" required><option value="">${t('Choose a country','选择国家')}</option>${['United States','United Kingdom','Germany','France','Canada','Australia','China','Japan','Singapore'].map(n=>`<option>${n}</option>`).join('')}</select></label><label class="field">${t('Address','详细地址')}<input name="address" required maxlength="120" placeholder="123 Demo Street" autocomplete="off"></label><div class="form-row"><label class="field">${t('City','城市')}<input name="city" required maxlength="60" placeholder="Demo City" autocomplete="off"></label><label class="field">${t('ZIP / postal code','邮政编码')}<input name="zip" required maxlength="20" placeholder="10001" autocomplete="off"></label></div><h3>${t('Delivery method','配送方式')}</h3><label class="shipping-option"><input type="radio" name="shipping" value="standard" ${state.shipping==='standard'?'checked':''}>${t('Standard · 5–8 business days','标准配送 · 5–8 个工作日')}<small>${o.subtotal-o.discount>=75?t('Free','免费'):money(8)}</small></label><label class="shipping-option"><input type="radio" name="shipping" value="express" ${state.shipping==='express'?'checked':''}>${t('Express · 2–4 business days','快递配送 · 2–4 个工作日')}<small>${money(15)}</small></label><p class="content-note">${t('Illustrative delivery times. Tax and duty are $0 in this demo; real checkout must calculate them by destination.','配送时效为示例。演示税费与关税为 $0；真实销售需按目的地计算。')}</p><h3>${t('Payment','支付方式')}</h3><div class="demo-notice">◈ ${t('Demo payment — always simulated. No card number required.','演示支付 — 全程模拟，无需卡号。')}</div><label class="check-label"><input type="checkbox" name="terms" required><span>${t('I understand this is a demo, no payment will be taken, and no goods will be shipped.','我了解这是演示订单，不产生真实扣款，也不实际发货。')}</span></label><p id="checkout-error" class="error-message" role="alert"></p><button type="submit" class="btn" id="pay-button" style="width:100%">${t('Place demo order','提交模拟订单')} · ${money(o.total)}</button><p class="cart-demo-note">${t('Base currency is USD. Other currencies are indicative display conversions.','以 USD 作为订单基准币种，其他币种仅作示例换算。')}</p></form><div class="checkout-summary"><h3>${t('Your little collection','订单商品')}</h3>${state.cart.map(orderLine).join('')}${state.giftInCart?`<div class="demo-notice">${t('Gift box included','包含礼盒包装')} · ${esc(state.giftInCart.note||t('With care','一份心意'))}</div>`:''}<div class="coupon-row"><input id="coupon" value="${esc(state.code)}" placeholder="${t('Try LUMA10','试试 LUMA10')}" aria-label="${t('Discount code','优惠码')}"><button type="button" class="btn secondary small" data-action="coupon">${t('Apply','应用')}</button></div><div id="checkout-totals">${summaryLines(o)}</div><a class="text-link" href="#shop">← ${t('Keep exploring','继续选购')}</a></div></div></section>`}
function ordersPage(){return `${intro(t('YOUR DEMO ORDERS','我的演示订单'),t('A little history of care.','你的心选记录。'),t('Orders are saved in this browser. All payments and tracking are simulated.','订单记录保存在当前浏览器，付款与物流状态均为演示。'))}<section class="section">${state.orders.length?state.orders.map(o=>`<article class="order-card"><div class="order-card-head"><div><h3>${esc(o.id)}</h3><small>${new Date(o.created_at).toLocaleString(state.lang==='zh'?'zh-CN':'en-US')}</small></div><span class="status-pill">${o.cancelled?t('Cancelled · demo','已取消 · 演示'):t('Confirmed · demo','已确认 · 演示')}</span></div>${o.lines.map(orderLine).join('')}<div class="summary-line total"><span>${t('Demo total','演示金额')}</span><strong>${money(o.total)}</strong></div>${o.gift?`<p class="content-note">${t('Gift message','礼盒留言')}: ${esc(o.gift.note||'—')}</p>`:''}<div class="tracking-steps"><span class="active">${t('Demo confirmed','演示确认')}</span><span>${t('Packing (simulated)','待打包（模拟）')}</span><span>${t('Not shipped','不实际发货')}</span></div><div class="btn-row"><button class="text-link" data-action="reorder" data-id="${esc(o.id)}">${t('Shop these again','再次购买')}</button>${!o.cancelled?`<button class="text-link" data-action="cancel-order" data-id="${esc(o.id)}">${t('Cancel demo order','取消演示订单')}</button>`:''}<button class="text-link" data-action="receipt" data-id="${esc(o.id)}">${t('Download demo receipt','下载演示收据')}</button></div></article>`).join(''):empty(t('Your first little ritual awaits.','第一份心选，等你开启。'),t('Complete a demo checkout to see an order here.','完成一次模拟结账，这里就会显示订单。'),'#shop',t('Explore the collection','探索全部商品'))}</section>`}
function successPage(){const id=location.hash.split('/')[1];const o=state.orders.find(x=>x.id===id);if(!o)return ordersPage();return `<section class="section success-panel"><div class="success-icon">✓</div><span class="eyebrow">DEMO ORDER CONFIRMED</span><h1>${t('A little thank you.','谢谢你，<br>这份小小心意。')}</h1><p>${t('Your demo order is confirmed. No money was charged and no shipment will be made.','你的演示订单已确认，没有扣取任何费用，也不会实际发货。')}</p><div class="demo-notice">${esc(o.id)} · ${money(o.total)}</div>${o.lines.map(orderLine).join('')}<div class="btn-row" style="justify-content:center;margin-top:30px"><a class="btn" href="#orders">${t('View demo order','查看演示订单')} ↗</a><a class="text-link" href="#shop">${t('Keep exploring','继续探索')}</a></div></section>`}
function infoPage(kind){const copy={about:{title:t('A little less. A little lovelier.','少一点，多一份美好。'),body:t(`<h2>A fictional brand, a complete experience.</h2><p>LUMA Ritual is an interactive skincare commerce demo. We imagine everyday care as a moment to slow down, with simple products and considered design.</p><h2>Explore at your own pace.</h2><p>Build a routine, discover digital textures, rotate packaging, compare essentials, shop an illustrated scene, or curate a gift. Everything leads to the same demo shopping bag.</p><h2>Clear about what’s real.</h2><p>Products, formulas, prices, skin suggestions, reviews and logistics are illustrative. We do not sell skincare, diagnose skin, process card payments, or dispatch goods.</p>`,`<h2>一个虚构品牌，一份完整体验。</h2><p>LUMA Ritual 是互动护肤商城演示。我们用简单商品和用心设计，想象一种更从容的日常护理。</p><h2>按自己的节奏探索。</h2><p>搭配护理、探索数字质地、旋转包装模型、对比商品、逛场景、定制礼盒。所有体验都连接同一个演示购物车。</p><h2>清楚说明演示边界。</h2><p>商品、配方、价格、肤质建议、评价和物流都是示例。不真实销售护肤品、不诊断肌肤、不处理银行卡付款、不实际发货。</p>`)},help:{title:t('A little help, right here.','一点帮助，就在这里。'),body:t(`<h2>Delivery</h2><p>Demo standard shipping is $8, free when the discounted product subtotal reaches $75. Demo express shipping is $15. Standard estimates are 5–8 business days; express estimates are 2–4. These are illustrations. No order is actually dispatched.</p><h2>Returns & refunds</h2><p>No money is collected, so no financial refunds are issued. You can cancel an order in My demo orders; cancellation changes its local demo status. The historical analytics order count remains unchanged. For a real store, return windows, exceptions, shipping costs and local consumer rules must be defined before launch.</p><h2>Payments & pricing</h2><p>Checkout only simulates payment. Use fictional details. USD is the base currency. EUR, GBP and CNY use fixed sample conversion rates, not live exchange rates. Tax and duty are $0 in this demo. Try LUMA10 for 10% off products.</p><h2>Contact</h2><p>This fictional brand has no staffed support inbox. For the demo, use the contact form below to generate a local support reference. Nothing is emailed or submitted to a third party.</p>`,`<h2>配送说明</h2><p>演示标准运费 $8，商品优惠后小计满 $75 免标准运费；快递运费 $15。演示标准时效 5–8 个工作日，快递 2–4 个工作日。均为示例，不会真正发货。</p><h2>退换货与退款</h2><p>演示不收款，因此没有真实退款。可在「我的演示订单」取消订单，仅改变当前浏览器内的演示状态，历史统计中的下单次数不会回退。真实商店上线前需另行确定退货期限、例外商品、运费承担及所在地消费者规则。</p><h2>付款与价格</h2><p>结账仅模拟支付，请填写虚构信息。USD 为基准币种，EUR、GBP、CNY 使用固定示例汇率，不是实时汇率。演示税费与关税为 $0。使用 LUMA10 可享商品九折。</p><h2>联系我们</h2><p>虚构品牌没有实际客服邮箱。下方表单可生成本地演示工单，不发送邮件，也不提交至第三方。</p>`)+`<form id="support-form"><label class="field">${t('Topic','问题类型')}<select required name="topic"><option>${t('Order question','订单问题')}</option><option>${t('Product question','商品问题')}</option><option>${t('Demo feedback','演示反馈')}</option></select></label><label class="field">${t('Message (fictional details only)','留言（请勿填写真实个人信息）')}<textarea name="message" required minlength="5" maxlength="1000" rows="4"></textarea></label><button class="btn" type="submit">${t('Create demo support reference','生成演示工单编号')}</button><p id="support-result" role="status"></p></form>`},privacy:{title:t('Clear, simple, considered.','清楚，简单，用心。'),body:t(`<h2>Local storage</h2><p>Your language, display currency, shopping bag, favorites, comparison list, gift design, consent choice and demo order history are stored in this browser. Checkout contact and address details stay in browser memory; they are not sent to our server.</p><h2>Optional anonymous analytics</h2><p>Only after you allow analytics, we send page views and interactions (product views, bag additions, checkout starts, and activity completions) with a random tab-session ID, coarse device class and country to this site. We do not store IP addresses or fingerprint your browser. Events are retained for up to 90 days and purged on subsequent event writes. Rejecting analytics does not disable shopping.</p><h2>Demo orders</h2><p>The server stores an order reference, selected product IDs, quantities, USD demo total and timestamp to make checkout and aggregated reporting work. An anonymous session is attached only when analytics is allowed. We do not collect card details, real payment data, names, addresses or emails. Order records are retained for the lifetime of this demo unless removed by the owner.</p><h2>Owner dashboard</h2><p>Aggregated reporting is password protected. A successful owner login sets an HttpOnly session cookie for one hour. Visitors cannot access the dashboard without the owner password.</p><h2>Demo terms</h2><p>This site is a fictional shopping demonstration. No purchase contract, efficacy guarantee, payment or fulfillment is created. Product suggestions and scores are illustrative. Do not rely on them to treat a skin condition.</p>`,`<h2>浏览器本地存储</h2><p>语言、显示币种、购物车、收藏、对比清单、礼盒设计、统计偏好及演示订单记录保存在当前浏览器。结账表单中的联系信息与地址仅存在浏览器内存，不发送至服务端。</p><h2>可选匿名统计</h2><p>仅在同意后，向本站发送浏览及互动事件（查看商品、加购、开始结账、完成互动等），附随机的标签页会话标识、粗略设备类型和国家。不保存 IP，不做浏览器指纹。事件最多保留 90 天，后续事件写入时清理过期记录。拒绝统计不影响购物。</p><h2>演示订单</h2><p>服务端保存订单编号、商品 ID、数量、USD 演示金额及时间，用于结账和汇总报表。仅在允许统计时关联匿名会话。不采集卡号、真实付款数据、姓名、地址或邮箱。订单记录在演示站存续期间保留，或由站长移除。</p><h2>站长后台</h2><p>汇总统计通过密码保护。登录成功设置有效期 1 小时的 HttpOnly 会话 Cookie。访客没有站长密码无法访问统计数据。</p><h2>演示条款</h2><p>本站为虚构购物演示，不形成购买合同、功效保证、真实付款或履约。产品建议与质地评分仅为示例，不能用于处理皮肤疾病。</p>`)}};const c=copy[kind]||copy.about;return `${intro('LUMA / WITH CARE',c.title,'')}<section class="section prose">${c.body}<p><a href="#shop">${t('Back to the collection ↗','返回商品系列 ↗')}</a></p></section>`}
async function analyticsPage(days=7){$('#main').innerHTML=intro('OWNER ANALYTICS',t('A little insight. A clearer picture.','看见数据，了解体验。'),t('Anonymous traffic and demo commerce. Real payments are never processed.','匿名访问与演示交易统计，不包含真实支付。'))+'<section class="section" id="analytics-content"><div class="loading">'+t('Loading analytics…','正在读取统计…')+'</div></section>';translateStatic();try{const res=await fetch('/api/stats?days='+days);if(res.status===401){$('#analytics-content').innerHTML=`<form class="analytics-login" id="analytics-login"><h3>${t('For the store owner','站长登录')}</h3><label class="field">${t('Analytics password','统计后台密码')}<input type="password" name="password" required autocomplete="current-password"></label><p class="error-message" id="login-error" role="alert"></p><button class="btn" type="submit">${t('Open dashboard','进入统计后台')} →</button></form>`;return}if(!res.ok)throw new Error(t('Statistics are temporarily unavailable.','统计暂时不可用。'));const d=await res.json();if(route()!=='analytics')return;renderStats(d)}catch(e){if(route()==='analytics')$('#analytics-content').innerHTML=`<p class="error-message">${esc(e.message)}</p><button class="btn secondary" data-action="analytics-refresh">${t('Try again','重试')}</button>`}}
function renderStats(d){const page=d.events.find(x=>x.name==='page_view')||{count:0,sessions:0};const count=n=>d.events.find(x=>x.name===n)?.count||0;const funnel=d.funnel||{};const max=funnel.visits||1;const chartDays=Array.from({length:d.days},(_,i)=>{const date=new Date(Date.now()-(d.days-1-i)*86400000).toISOString().slice(0,10);return {day:date,...d.daily.find(x=>x.day===date)}});const top=Math.max(1,...chartDays.map(x=>x.views||0));const bars=chartDays.map((v,i)=>{const w=560/chartDays.length;const h=(v.views||0)/top*145;return `<rect x="${20+i*w}" y="${170-h}" width="${Math.max(2,w-5)}" height="${h}" rx="2" fill="#8d9f7b"><title>${v.day}: ${v.views||0} ${t('views','浏览')}</title></rect>${(i===0||i===chartDays.length-1||i===Math.floor(chartDays.length/2))?`<text x="${20+i*w}" y="195" fill="#79816f" font-size="10">${v.day.slice(5)}</text>`:''}`}).join('');$('#analytics-content').innerHTML=`<div class="workspace-heading"><div class="chips">${[7,30,90].map(n=>`<button class="chip ${d.days===n?'active':''}" data-action="analytics-days" data-id="${n}">${n} ${t('days','天')}</button>`).join('')}</div><div class="btn-row"><button class="text-link" data-action="analytics-export">${t('Export CSV','导出 CSV')}</button><button class="text-link" data-action="analytics-refresh">${t('Refresh','刷新')}</button><button class="text-link" data-action="analytics-logout">${t('Log out','退出')}</button></div></div><p class="analytics-note">${t('UTC date buckets · consented traffic only · session means one browser tab · demo order totals include orders without analytics consent.','按 UTC 日期汇总 · 仅统计同意后的访问 · 会话指一个浏览器标签页 · 演示订单汇总包含未同意统计的订单。')}</p><div class="metric-grid">${[[t('Page views','页面浏览 PV'),page.count],[t('Anonymous sessions','匿名会话'),page.sessions],[t('Demo orders','演示订单'),d.orders.count],[t('Demo order value (USD)','演示订单金额（USD）'),'$'+Number(d.orders.revenue).toFixed(2)]].map(([n,v])=>`<div class="metric"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><div class="chart-grid"><div class="chart-panel"><h3>${t('Daily visits','每日访问趋势')}</h3><svg viewBox="0 0 620 220" role="img" aria-label="${t('Daily page views chart','每日页面浏览图')}"><line x1="20" x2="600" y1="170" y2="170" stroke="#d0d5c6"/><text x="20" y="15" font-size="10" fill="#79816f">${t('Peak','峰值')}: ${top} PV</text>${bars}</svg>${!page.count?`<p class="analytics-note">${t('No consented visits in this period yet.','所选时段暂无同意统计的访问。')}</p>`:''}</div><div class="chart-panel"><h3>${t('Shopping journey','购物转化漏斗')}</h3>${[[t('Visited','访问'),funnel.visits],[t('Viewed a product','查看商品'),funnel.viewed],[t('Added to bag','加入购物车'),funnel.added],[t('Started checkout','开始结账'),funnel.checked],[t('Placed demo order','完成演示订单'),funnel.purchased]].map(([n,v])=>`<div class="funnel-row"><div class="summary-line"><span>${n}</span><span>${v||0} · ${Math.round((v||0)/max*100)}%</span></div><div class="bar-track"><i style="width:${(v||0)/max*100}%"></i></div></div>`).join('')}<p class="analytics-note">${t('Ordered steps in the same anonymous session; percentages are relative to visits.','按同一匿名会话中的先后步骤去重，百分比以访问会话为基准。')}</p></div></div><div class="chart-grid"><div class="chart-panel"><h3>${t('Product interest','商品热度')}</h3><table class="data-table"><thead><tr><th>${t('Product','商品')}</th><th>${t('Views','查看')}</th><th>${t('Bag adds','加购')}</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(pname(p))}</td><td>${d.products.find(x=>x.product_id===p.id&&x.name==='view_item')?.count||0}</td><td>${d.products.find(x=>x.product_id===p.id&&x.name==='add_to_cart')?.count||0}</td></tr>`).join('')}</tbody></table></div><div class="chart-panel"><h3>${t('Explore & interact','互动功能使用')}</h3><table class="data-table"><tbody>${[['quiz_complete',t('Preference guide completed','完成偏好向导')],['routine_add',t('Rituals added','搭配加购')],['gift_add',t('Gifts added','礼盒加购')],['compare',t('Comparisons opened','打开商品对比')],['texture_view',t('Textures explored','探索质地')],['scene_click',t('Scene hotspots','场景热点点击')],['rotate_product',t('360° models opened','打开 360° 模型')]].map(([n,label])=>`<tr><td>${label}</td><td>${count(n)}</td></tr>`).join('')}</tbody></table></div></div><div class="chart-grid"><div class="chart-panel"><h3>${t('Countries','访问国家')}</h3><table class="data-table"><tbody>${d.countries.length?d.countries.map(x=>`<tr><td>${esc(x.country)}</td><td>${x.count} ${t('sessions','会话')}</td></tr>`).join(''):`<tr><td>${t('No data yet','暂无数据')}</td></tr>`}</tbody></table></div><div class="chart-panel"><h3>${t('Devices','设备分布')}</h3><table class="data-table"><tbody>${d.devices.length?d.devices.map(x=>`<tr><td>${x.device==='mobile'?t('Mobile','移动端'):t('Desktop','桌面端')}</td><td>${x.count} ${t('sessions','会话')}</td></tr>`).join(''):`<tr><td>${t('No data yet','暂无数据')}</td></tr>`}</tbody></table></div></div><p class="analytics-note">${t('Updated','更新于')}: ${new Date(d.updatedAt).toLocaleString()} · ${t('All revenue is simulated. Cancellations are local demo status changes and do not subtract historical order value.','全部金额均为模拟；取消仅改变本地演示状态，不冲减历史下单金额。')}</p>`;window.lumaStats=d;}
function render({scroll=true,tracking=true}={}){const r=route();const p=getProduct(location.hash.split('/')[1]);if(r==='analytics'){analyticsPage();return}const pages={home,shop:()=>shop(),favorites:()=>shop(true),product:()=>productPage(p),routine:routinePage,quiz:quizPage,texture:texturePage,gift:giftPage,scene:scenePage,compare:comparePage,checkout:checkoutPage,orders:ordersPage,success:successPage,about:()=>infoPage('about'),help:()=>infoPage('help'),privacy:()=>infoPage('privacy')};$('#main').innerHTML=(pages[r]||home)();translateStatic();if(r==='checkout')for(const [key,value] of Object.entries(checkoutDraft)){const input=$('#checkout-form [name="'+key+'"]');if(input){if(input.type==='checkbox')input.checked=value;else input.value=value}}updateCompareDock();if(scroll)window.scrollTo(0,0);document.title=(p&&r==='product'?pname(p)+' — ':'')+'LUMA Ritual · '+t('A little ritual. A softer day.','一点仪式感，柔软每一天。');if(tracking){track('page_view');if(r==='product'&&p)track('view_item',p.id);if(r==='checkout'&&state.cart.length)track('begin_checkout');if(r==='compare')track('compare');if(r==='texture')track('texture_view')};}
function updateCompareDock(){$('.compare-dock')?.remove();if(state.compare.length&&route()!=='compare'&&route()!=='checkout'&&route()!=='analytics'){const a=document.createElement('a');a.href='#compare';a.className='compare-dock';a.textContent=t('Compare your edit','对比心选商品')+' ('+state.compare.length+'/3) ↗';document.body.append(a)}}
function addItems(ids,quantity=1){checkoutKey=null;for(const id of ids){if(!getProduct(id))continue;const i=state.cart.find(x=>x.id===id);if(i)i.qty=Math.min(20,i.qty+quantity);else state.cart.push({id,qty:Math.min(20,quantity)});track('add_to_cart',id)}saveCart();toast(t('A little care, added to your bag.','心选好物，已加入购物车。'));if(!$('#cart').hidden)renderCart()}
let lastFocus;
function openCart(){lastFocus=document.activeElement;renderCart();$('#cart').hidden=false;$('#cart-overlay').hidden=false;document.body.style.overflow='hidden';$('#cart').focus()}
function closeCart(){$('#cart').hidden=true;$('#cart-overlay').hidden=true;document.body.style.overflow='';lastFocus?.focus()}
function renderCart(){const o=cartOrder();const amount=o?o.subtotal-o.discount:0;$('#cart-body').innerHTML=o?`<div class="shipping-progress">${amount>=75?t('Your bag qualifies for complimentary standard shipping.','你的购物车已享免费标准配送。'):t('You’re '+money(75-amount)+' away from complimentary standard shipping.','再选 '+money(75-amount)+' 即可享免费标准配送。')}<div class="bar-track"><i style="width:${Math.min(100,amount/75*100)}%"></i></div></div>${state.cart.map(i=>{const p=getProduct(i.id);return `<div class="cart-line">${art(p)}<div class="cart-item-content"><h3><a href="#product/${p.id}" data-close-cart>${esc(pname(p))}</a></h3><small>${p.size} · ${money(p.price)}</small><div style="display:flex;justify-content:space-between;align-items:end"><div class="quantity"><button data-action="cart-minus" data-id="i:${p.id}" aria-label="Decrease ${esc(pname(p))}">−</button><span>${i.qty}</span><button data-action="cart-plus" data-id="i:${p.id}" aria-label="Increase ${esc(pname(p))}">+</button></div><strong>${money(p.price*i.qty)}</strong></div><button class="remove-item" data-action="cart-remove" data-id="i:${p.id}">${t('Remove','移除')}</button></div></div>`}).join('')}${state.giftInCart?`<div class="demo-notice">${t('Gift packaging','礼盒包装')} · ${money(6)}<br>${esc(state.giftInCart.note||t('With care','一份心意'))}<br><button class="text-link" data-action="gift-remove">${t('Remove packaging','移除包装')}</button></div>`:''}<div class="cart-summary">${summaryLines(o)}<a href="#checkout" class="btn" data-close-cart>${t('Demo checkout','模拟结账')} ↗</a><p class="cart-demo-note">${t('No real payment. No real shipment.','不真实收款，不实际发货。')}</p></div>`:empty(t('Room for a little care.','给关怀，留一点位置。'),t('Your shopping bag is empty.','你的购物车还是空的。'),'#shop',t('Explore essentials','探索心选'))}
function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else{toast(t('Compare up to three essentials.','最多同时对比 3 件商品。'));return false}persist('compare',state.compare);return true}
function showProductModal(p){$('#modal-content').innerHTML=`<div class="modal-content-grid">${art(p)}<div><span class="eyebrow">${esc(state.lang==='zh'?p.tagZh:p.tag)}</span><h2>${esc(pname(p))}</h2><p>${esc(desc(p))}</p><p>${money(p.price)} · ${p.size}</p><div class="btn-row"><button class="btn" data-action="modal-add" data-id="${p.id}">${t('Add to bag','加入购物车')} +</button><a class="text-link" href="#product/${p.id}" data-close-modal>${t('View details','查看详情')} ↗</a></div></div></div>`;$('#modal').showModal()}
function showRotate(p){track('rotate_product',p.id);$('#modal-content').innerHTML=`<span class="eyebrow">THE PACKAGING STUDY / 360°</span><h2>${esc(pname(p))}</h2><div class="rotate-stage" id="rotate-stage"><div class="model-3d" id="model-3d" style="--bottle:${p.color};--rotation:25deg"><div class="model-cap"></div><div class="model-face model-front"><div class="bottle-label"><b>luma</b><small>R I T U A L</small><em>${esc(p.name)}</em><span>${p.tag}<br>${p.size}</span></div></div><div class="model-face model-back">LUMA RITUAL<br><br>${p.ingredients.join(' · ')}<br><br>CONCEPT PACKAGING<br>DEMO ONLY<br><br>▥▥▥▥▥▥▥</div><div class="model-face model-left"></div><div class="model-face model-right"></div><div class="model-face model-top"></div><div class="model-face model-bottom"></div></div></div><label class="rotate-instructions" for="rotation">${t('Drag to rotate, or use the slider / arrow keys. This is an interactive concept packaging model.','拖动旋转，或使用滑块及方向键。这是可交互的概念包装模型。')}</label><input class="rotation-slider" id="rotation" aria-label="${t('Product rotation angle','商品旋转角度')}" type="range" min="0" max="360" value="25"><div class="btn-row"><button class="btn secondary small" data-action="rotate-reset">${t('Reset angle','重置角度')}</button><button class="btn small" data-action="modal-add" data-id="${p.id}">${t('Add to bag','加入购物车')} +</button></div>`;$('#modal').showModal();let start=0,base=25;const stage=$('#rotate-stage');stage.addEventListener('pointerdown',e=>{start=e.clientX;base=Number($('#rotation').value);stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!stage.hasPointerCapture(e.pointerId))return;const v=((base+(e.clientX-start)*1.4)%360+360)%360;$('#rotation').value=v;$('#model-3d').style.setProperty('--rotation',v+'deg')});}
function showConsent(force=false){if(state.consent!==null&&!force){$('#consent').hidden=true;return}$('#consent').hidden=false;$('#consent').innerHTML=`<div class="consent-banner"><p><strong>${t('A little insight, with your permission.','得到你的允许，再了解一点。')}</strong><br>${t('Allow anonymous visit and shopping interaction statistics? No IP addresses or contact details are stored.','允许收集匿名访问和购物互动统计吗？不保存 IP 或联系信息。')} <a href="#privacy" class="text-link">${t('Details','详情')}</a></p><div class="btn-row"><button class="btn small" data-action="consent-allow">${t('Allow analytics','允许匿名统计')}</button><button class="btn secondary small" data-action="consent-reject">${t('Essential only','仅必要功能')}</button></div></div>`}
let checkoutKey=null;let checkoutBusy=false;const checkoutDraft={};
async function submitCheckout(form){const error=$('#checkout-error');const button=$('#pay-button');if(checkoutBusy||!form.reportValidity())return;checkoutBusy=true;button.disabled=true;button.textContent=t('Confirming demo order…','正在确认演示订单…');error.textContent='';checkoutKey ||= crypto.randomUUID();try{const res=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:checkoutKey,items:state.cart,code:state.code,shipping:state.shipping,gift:!!state.giftInCart,session:state.consent===true?session:null})});const result=await res.json();if(!res.ok)throw new Error(result.error||'Order failed');const o={...result,lines:result.lines||cartOrder().lines,gift:state.giftInCart};state.orders.unshift(o);persist('orders',state.orders);state.cart=[];state.giftInCart=null;state.code='';persist('code','');saveCart();checkoutKey=null;location.hash='#success/'+o.id}catch(e){error.textContent=t('Could not confirm the order. Your bag is saved. Please retry.','订单未能确认，购物车已保留，请重试。');button.disabled=false;button.textContent=t('Retry demo order','重试模拟下单')}finally{checkoutBusy=false}}
function refreshCheckoutTotals(){const o=cartOrder();if(!o)return;$('#checkout-totals').innerHTML=summaryLines(o);$('#pay-button').textContent=t('Place demo order','提交模拟订单')+' · '+money(o.total)}
function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',async e=>{const closeLink=e.target.closest('[data-close-cart]');if(closeLink)closeCart();if(e.target.closest('[data-close-modal]'))$('#modal').close();const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,p=getProduct(id);if(el.disabled)return;
 if(a==='add'||a==='detail-add'||a==='modal-add'){addItems([id],a==='detail-add'?state.qty:1);if(a==='modal-add')$('#modal').close();openCart()}
 else if(a==='favorite'){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist('favorites',state.favorites);render({scroll:false,tracking:false})}
 else if(a==='compare-toggle'){if(el.type==='checkbox')return;if(toggleCompare(id))render({scroll:false,tracking:false})}
 else if(a==='category'){state.category=id;render({scroll:false,tracking:false})}
 else if(a==='detail-minus'||a==='detail-plus'){state.qty=Math.max(1,Math.min(20,state.qty+(a==='detail-plus'?1:-1)));render({scroll:false,tracking:false})}
 else if(a==='rotate')showRotate(p);
 else if(a==='texture-link'){state.texture=p.texture;location.hash='#texture'}
 else if(a==='texture'){state.texture=id;render({scroll:false,tracking:false});track('texture_view')}
 else if(a==='spread')$('#texture-stage')?.classList.toggle('spread');
 else if(a==='reset-texture'){$('#texture-stage').classList.remove('spread');$('#texture-stage').style.filter='';$('#texture-light').value=100}
 else if(a==='period'){state.period=id;render({scroll:false,tracking:false})}
 else if(a==='routine-pick'){state.routine[p.category]=p.id;persist('routine',state.routine);render({scroll:false,tracking:false});toast(t('Added to your ritual.','已加入护理搭配。'))}
 else if(a==='routine-add'){const steps=state.period==='am'?['cleanse','serum','moisturize','protect']:['cleanse','serum','moisturize'];addItems(steps.map(s=>state.routine[s]).filter(x=>getProduct(x)));track('routine_add');openCart()}
 else if(a==='quiz-option'){state.quiz[el.dataset.key]=id;render({scroll:false,tracking:false})}
 else if(a==='quiz-next'){state.quizStep++;if(state.quizStep===3)track('quiz_complete');render({scroll:false,tracking:false})}
 else if(a==='quiz-back'){state.quizStep--;render({scroll:false,tracking:false})}
 else if(a==='quiz-reset'){state.quizStep=0;state.quiz={skin:'',goal:'',time:''};render({scroll:false,tracking:false})}
 else if(a==='quiz-routine'){const rec=quizRecommendations();rec.forEach(p=>state.routine[p.category]=p.id);state.period=state.quiz.time||'am';persist('routine',state.routine);location.hash='#routine'}
 else if(a==='gift-pick'){if(state.gift.ids.includes(id))state.gift.ids=state.gift.ids.filter(x=>x!==id);else if(state.gift.ids.length<3)state.gift.ids.push(id);else{toast(t('A little box fits up to three essentials.','一个礼盒最多选择 3 件商品。'));return}persist('gift',state.gift);render({scroll:false,tracking:false})}
 else if(a==='gift-color'){state.gift.color=id;persist('gift',state.gift);render({scroll:false,tracking:false})}
 else if(a==='gift-add'){if(state.giftInCart){toast(t('Your bag already has a gift box. Remove its packaging first to create a new one.','购物车已有礼盒，请先移除原包装再添加新礼盒。'));openCart();return}state.giftInCart=structuredClone(state.gift);addItems(state.gift.ids);track('gift_add');saveCart();openCart()}
 else if(a==='gift-remove'){state.giftInCart=null;saveCart();renderCart();if(route()==='checkout')render({scroll:false,tracking:false})}
 else if(a==='scene-product'){track('scene_click',id);track('view_item',id);showProductModal(p)}
 else if(a==='scene-add-all'){addItems(products.slice(0,3).map(p=>p.id));openCart()}
 else if(a==='compare-clear'){state.compare=[];persist('compare',[]);render({scroll:false,tracking:false})}
 else if(a.startsWith('cart-')){const pid=id.slice(2);const item=state.cart.find(x=>x.id===pid);if(!item)return;checkoutKey=null;if(a==='cart-plus')item.qty=Math.min(20,item.qty+1);if(a==='cart-minus')item.qty--;if(a==='cart-remove')item.qty=0;state.cart=state.cart.filter(i=>i.qty>0);if(state.giftInCart?.ids.includes(pid)&&!state.cart.some(i=>i.id===pid)){state.giftInCart.ids=state.giftInCart.ids.filter(x=>x!==pid);if(!state.giftInCart.ids.length)state.giftInCart=null}saveCart();renderCart();if(route()==='checkout')render({scroll:false,tracking:false})}
 else if(a==='coupon'){const code=$('#coupon').value.trim().toUpperCase();if(code&&code!=='LUMA10'){toast(t('Try LUMA10 for 10% off.','请输入 LUMA10 享九折。'));return}state.code=code;persist('code',code);checkoutKey=null;refreshCheckoutTotals();toast(t('Your bag has been updated.','订单金额已更新。'))}
 else if(a==='reorder'){const o=state.orders.find(x=>x.id===id);o?.lines.forEach(i=>addItems([i.id],i.qty));openCart()}
 else if(a==='cancel-order'){const o=state.orders.find(x=>x.id===id);if(o){o.cancelled=true;persist('orders',state.orders);render({scroll:false,tracking:false});toast(t('Demo order cancelled locally. No refund is needed.','本地演示订单已取消，无需真实退款。'))}}
 else if(a==='receipt'){const o=state.orders.find(x=>x.id===id);if(o)download(o.id+'-DEMO.txt',`LUMA RITUAL — DEMO RECEIPT\nNo payment collected / No shipment\n${o.id}\n${new Date(o.created_at).toISOString()}\n\n${o.lines.map(i=>`${i.name} × ${i.qty} — USD ${(i.price*i.qty).toFixed(2)}`).join('\n')}\n\nDemo total: USD ${o.total.toFixed(2)}\n`) }
 else if(a==='rotate-reset'){$('#rotation').value=25;$('#model-3d').style.setProperty('--rotation','25deg')}
 else if(a==='consent-settings')showConsent(true);
 else if(a==='consent-allow'||a==='consent-reject'){state.consent=a==='consent-allow';persist('consent',state.consent);showConsent();if(state.consent){track('page_view');const p=getProduct(location.hash.split('/')[1]);if(route()==='product'&&p)track('view_item',p.id)}}
 else if(a==='analytics-days')analyticsPage(Number(id));
 else if(a==='analytics-refresh')analyticsPage(window.lumaStats?.days||7);
 else if(a==='analytics-logout'){await fetch('/api/admin/logout',{method:'POST'});window.lumaStats=null;analyticsPage()}
 else if(a==='analytics-export'){const d=window.lumaStats;if(d){const rows=[['Metric','Value'],['Period days',d.days],['Demo orders',d.orders.count],['Demo order value USD',d.orders.revenue],...d.events.map(e=>['Event: '+e.name,e.count]),[],['UTC date','Page views','Sessions'],...d.daily.map(x=>[x.day,x.views,x.sessions])];download('luma-analytics.csv','\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv;charset=utf-8')}}
});
document.addEventListener('input',e=>{const el=e.target;if(el.closest('#checkout-form')&&el.name&&el.name!=='shipping')checkoutDraft[el.name]=el.type==='checkbox'?el.checked:el.value;if(el.id==='search'){const pos=el.selectionStart;state.search=el.value;render({scroll:false,tracking:false});$('#search').focus();try{$('#search').setSelectionRange(pos,pos)}catch{}}
 if(el.id==='max-price'){state.maxPrice=Number(el.value);const focused=document.activeElement===el;render({scroll:false,tracking:false});if(focused)$('#max-price').focus()}
 if(el.id==='gift-note'){state.gift.note=el.value;persist('gift',state.gift);$('#gift-card-preview').textContent=el.value||t('A little something, just for you.','一点小心意，送给特别的你。')}
 if(el.id==='texture-light')$('#texture-stage').style.filter=`brightness(${el.value}%)`;
 if(el.id==='rotation')$('#model-3d').style.setProperty('--rotation',el.value+'deg');
});
document.addEventListener('change',e=>{const el=e.target;if(el.closest('#checkout-form')&&el.name&&el.name!=='shipping')checkoutDraft[el.name]=el.type==='checkbox'?el.checked:el.value;if(el.id==='language'){state.lang=el.value;persist('lang',state.lang);render({scroll:false,tracking:false});if(!$('#cart').hidden)renderCart();showConsent()}
 if(el.id==='currency'){state.currency=el.value;persist('currency',state.currency);render({scroll:false,tracking:false});if(!$('#cart').hidden)renderCart()}
 if(el.id==='sort'){state.sort=el.value;render({scroll:false,tracking:false})}
 if(el.dataset.action==='compare-toggle'){if(!toggleCompare(el.dataset.id))el.checked=false;updateCompareDock();if(route()==='compare')render({scroll:false,tracking:false})}
 if(el.dataset.routine){state.routine[el.dataset.routine]=el.value;persist('routine',state.routine);render({scroll:false,tracking:false})}
 if(el.name==='shipping'){state.shipping=el.value;checkoutKey=null;refreshCheckoutTotals()}
});
document.addEventListener('submit',async e=>{if(e.target.id==='checkout-form'){e.preventDefault();submitCheckout(e.target)}
 if(e.target.id==='analytics-login'){e.preventDefault();const button=$('button',e.target);button.disabled=true;try{const res=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:new FormData(e.target).get('password')})});if(!res.ok)throw new Error();analyticsPage()}catch{$('#login-error').textContent=t('Could not sign in. Check your password and try again.','无法登录，请检查密码后重试。');button.disabled=false}}
 if(e.target.id==='support-form'){e.preventDefault();$('#support-result').textContent=t('Local demo reference: ','本地演示工单：')+'HELP-'+crypto.randomUUID().slice(0,8).toUpperCase()+t(' · No message was sent.',' · 未发送任何消息。');e.target.reset()}
});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[draggable][data-product]');if(card)e.dataTransfer.setData('text/plain',card.dataset.product)});
document.addEventListener('dragover',e=>{const slot=e.target.closest('[data-step]');if(slot){e.preventDefault();slot.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>e.target.closest('[data-step]')?.classList.remove('drag-over'));
document.addEventListener('drop',e=>{const slot=e.target.closest('[data-step]');if(!slot)return;e.preventDefault();const p=getProduct(e.dataTransfer.getData('text/plain'));if(p?.category===slot.dataset.step){state.routine[p.category]=p.id;persist('routine',state.routine);render({scroll:false,tracking:false});toast(t('A little change, made.','搭配已更新。'))}else{slot.classList.remove('drag-over');toast(t('Choose an essential for this matching step.','请选择与此护理步骤对应的商品。'))}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#cart').hidden)closeCart();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action="rotate"]')){e.preventDefault();showRotate(getProduct(e.target.dataset.id))}if((e.key==='Enter'||e.key===' ')&&e.target.id==='texture-stage'){e.preventDefault();e.target.classList.toggle('spread')}if(e.key==='Tab'&&!$('#cart').hidden){const focusables=$$('a,button,input,select,[tabindex="0"]',$('#cart')).filter(x=>!x.disabled);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#cart'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#cart-open').addEventListener('click',openCart);$('#cart-close').addEventListener('click',closeCart);$('#cart-overlay').addEventListener('click',closeCart);$('.modal-close').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});$('#mobile-menu').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#mobile-menu').setAttribute('aria-expanded',open)});document.addEventListener('click',e=>{if(e.target.closest('#texture-stage'))$('#texture-stage').classList.toggle('spread')});
window.addEventListener('hashchange',()=>{closeCart();$('#modal').close();document.body.classList.remove('nav-open');$('#mobile-menu').setAttribute('aria-expanded','false');state.qty=1;render();$('#main').focus({preventScroll:true})});
window.addEventListener('storage',e=>{if(e.key==='luma-cart'){state.cart=read('cart',[]);updateCartCount();if(!$('#cart').hidden)renderCart()}});
translateStatic();render();showConsent();
